package akogen.fabric.v6;
import java.util.*;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.*;import com.google.gson.*;
public final class Session implements InvocationHandler,Runnable{
 public static Object mc;public static volatile boolean active;public static String logPath;public static Class<?> screenType;public static Map<String,Assets.Entry> equipped=new LinkedHashMap<String,Assets.Entry>();public static long begin=System.nanoTime();static boolean homeDown;static String lastError;int mode;
 public Session(int mode){this.mode=mode;}
 public static synchronized void log(String s){if(logPath==null)return;try(Writer w=new OutputStreamWriter(new FileOutputStream(logPath,true),"UTF-8")){w.write(new Date()+" "+s+"\n");}catch(Exception ignored){}}
 public static void error(Throwable t){while(t instanceof InvocationTargetException&&t.getCause()!=null)t=t.getCause();String s=t.toString();if(!s.equals(lastError)){lastError=s;log("ERROR: "+s);}}
 public static void start(Class<?> minecraft,ClassLoader loader,byte[] pack,byte[] mappings,String path)throws Exception{logPath=path;if(active){log("OK: Fabric cosmetics ready; already active; press Home");return;}Names.loader=loader;Names.names=new JsonParser().parse(new String(mappings,"UTF-8")).getAsJsonObject();logPath=path;

 Object fabric=Names.call(Class.forName("net.fabricmc.loader.api.FabricLoader",true,loader),"getInstance");Object mod=((Optional<?>)Names.call(fabric,"getModContainer","minecraft")).get();String version=String.valueOf(Names.call(Names.call(Names.call(mod,"getMetadata"),"getVersion"),"getFriendlyString"));if(!version.equals("1.21.11"))throw new IllegalStateException("This application supports Minecraft 1.21.11; detected "+version);
 CosmeticSync.catalog=SyncCodec.hash(pack).substring(0,24);Assets.load(pack);mc=Names.call(minecraft,"getInstance");screenType=Class.forName("akogen.fabric.v6.HomeScreen",true,loader);((Executor)mc).execute(new Session(2));log("READY: Fabric 1.21.11 detected; independent wardrobe installation queued");}
 public void run(){try{register("net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents","END_CLIENT_TICK","net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents$EndTick",0);register("net.fabricmc.fabric.api.client.rendering.v1.world.WorldRenderEvents","AFTER_ENTITIES","net.fabricmc.fabric.api.client.rendering.v1.world.WorldRenderEvents$AfterEntities",1);active=true;Visibility.load();loadSelection();CosmeticSync.start();Object current=Names.field(mc,"screen");if(current!=null&&current.getClass().getName().startsWith("akogen.fabric."))Names.call(mc,"setScreen",screenType.getConstructor().newInstance());log("OK: Fabric cosmetics ready; Home opens wardrobe; "+Assets.entries.size()+" custom cosmetics; independent Fabric renderer");}catch(Throwable t){error(t);}}
 static void register(String type,String field,String callback,int mode)throws Exception{Class<?> c=Class.forName(type,true,Names.loader);Object event=c.getField(field).get(null);Object proxy=Proxy.newProxyInstance(Names.loader,new Class[]{Class.forName(callback,true,Names.loader)},new Session(mode));Names.call(event,"register",proxy);}
 public Object invoke(Object proxy,Method method,Object[] args){if(method.getDeclaringClass()==Object.class){if(method.getName().equals("toString"))return"Akogen Fabric callback";if(method.getName().equals("hashCode"))return System.identityHashCode(proxy);return args!=null&&args[0]==proxy;}if(!active)return null;try{if(mode==0)tick();else World.draw(args[0]);}catch(Throwable t){error(t);}return null;}
 static void tick()throws Exception{try{CosmeticSync.tick();}catch(Throwable t){error(t);}try{CapeBridge.tick();}catch(Throwable t){error(t);}long window=((Number)Names.call(Names.call(mc,"getWindow"),"handle")).longValue();Class<?> glfw=Class.forName("org.lwjgl.glfw.GLFW",true,Names.loader);boolean down=((Number)Names.call(glfw,"glfwGetKey",window,268)).intValue()==1;if(down&&!homeDown){Object current=Names.field(mc,"screen");if(current==null||screenType.isInstance(current))toggle();}homeDown=down;}
 public static void toggle()throws Exception{Object current=Names.field(mc,"screen");Names.call(mc,"setScreen",screenType.isInstance(current)?null:screenType.getConstructor().newInstance());}
 public static boolean isEquipped(Assets.Entry e){return equipped.containsValue(e);}
 public static int flyingCount(){int n=0;for(Assets.Entry e:equipped.values())if(e.slot.equals("flying"))n++;return n;}
 static boolean install(Assets.Entry e)throws Exception{String key=e.slot;if(e.slot.equals("flying")){if(flyingCount()>=2){Iterator<Map.Entry<String,Assets.Entry>> oldest=equipped.entrySet().iterator();while(oldest.hasNext())if(oldest.next().getValue().slot.equals("flying")){oldest.remove();break;}}key=equipped.containsKey("flying:0")?"flying:1":"flying:0";}Assets.prepare(e);equipped.put(key,e);e.placed=false;return true;}
 public static void choose(Assets.Entry e){try{if(isEquipped(e)){Iterator<Map.Entry<String,Assets.Entry>> i=equipped.entrySet().iterator();while(i.hasNext())if(i.next().getValue()==e){i.remove();break;}}else if(!install(e))return;try{CapeBridge.tick();}catch(Throwable t){error(t);}saveSelection();log("SELECTED: "+e.name+" / "+e.slot+"; flying "+flyingCount()+"/2");}catch(Throwable t){error(t);Ui.notice="Could not load "+e.name;}}
 static File selectionFile(){return new File(new File(logPath).getParentFile(),"wardrobe.json");}
 static void saveSelection(){try(Writer w=new OutputStreamWriter(new FileOutputStream(selectionFile()),"UTF-8")){JsonArray a=new JsonArray();for(Assets.Entry e:equipped.values())a.add(e.id);w.write(a.toString());}catch(Exception e){error(e);}}
 static void loadSelection(){File file=selectionFile();if(!file.isFile())return;try(Reader r=new InputStreamReader(new FileInputStream(file),"UTF-8")){JsonArray a=new JsonParser().parse(r).getAsJsonArray();for(JsonElement id:a)for(Assets.Entry e:Assets.entries)if(e.id==id.getAsInt()){install(e);}}catch(Exception e){error(e);}}
 public static double time(){return (System.nanoTime()-begin)/1e9;}
}
